import { useState } from 'react';
import { Box, TextField, Button } from '@mui/material';
import axios from 'axios';

const endpointMapping = {
    'Notion': 'notion',
    'Airtable': 'airtable',
    'HubSpot': 'hubspot',
};

export const DataForm = ({ integrationType, credentials }) => {
    const [loadedData, setLoadedData] = useState(null);
    const endpoint = endpointMapping[integrationType];

    const handleLoad = async () => {
        if (!credentials) return alert("No credentials available.");

        try {
            const formData = new FormData();
            formData.append('credentials', JSON.stringify(credentials));

            const response = await axios.post(
                `http://localhost:8000/integrations/${endpoint}/load`,
                formData,
                { headers: { 'Content-Type': 'multipart/form-data' } }
            );

            console.log("Loaded data:", response.data);
            setLoadedData(response.data);
        } catch (e) {
            console.error(e);
            alert(e?.response?.data?.detail || e.message);
        }
    }

    return (
        <Box display='flex' flexDirection='column' width='100%' alignItems='center'>
            <TextField
                label="Loaded Data"
                value={loadedData ? JSON.stringify(loadedData, null, 2) : ''}
                multiline
                minRows={6}
                fullWidth
                sx={{ mt: 2 }}
                InputLabelProps={{ shrink: true }}
                disabled
            />
            <Button sx={{ mt: 2 }} variant="contained" onClick={handleLoad}>
                Load Data
            </Button>
            <Button sx={{ mt: 1 }} variant="contained" onClick={() => setLoadedData(null)}>
                Clear Data
            </Button>
        </Box>
    );
}
